import {runExperiment} from './engine.js';
const $ = id => document.getElementById(id);
const sensors=['Z1_S1','Z1_S2','Z1_S3','Z2_S1','Z2_S2','Z2_S3'];
const positions={R_SUP:[55,210],J_MAIN_IN:[130,210],J_Z1_IN:[205,210],Z1_S1:[280,110],Z1_S2:[280,210],Z1_S3:[280,310],J_Z1_OUT:[355,210],J_MAIN_MID:[425,210],J_Z2_IN:[490,210],Z2_S1:[570,110],Z2_S2:[570,210],Z2_S3:[570,310],J_Z2_OUT:[650,210],T_OUT:[730,210]};
function drawNetwork(){let lines='';for(const [a,b] of [['R_SUP','J_MAIN_IN'],['J_MAIN_IN','J_Z1_IN'],...sensors.slice(0,3).flatMap(n=>[['J_Z1_IN',n],[n,'J_Z1_OUT']]),['J_Z1_OUT','J_MAIN_MID'],['J_MAIN_MID','J_Z2_IN'],...sensors.slice(3).flatMap(n=>[['J_Z2_IN',n],[n,'J_Z2_OUT']]),['J_Z2_OUT','T_OUT']]){const p=positions[a],q=positions[b];lines+=`<path d="M${p} L${q}" stroke="#3f6479" stroke-width="4" fill="none"/>`;} $('network').innerHTML=`<svg viewBox="0 0 790 400" role="group" aria-label="Two zones with three pressure sensors each. Select a sensor to configure a leak."><text x="280" y="35" text-anchor="middle" fill="#a5b4c6" font-size="14">ZONE 01 · EQUAL BRANCH LENGTHS</text><text x="570" y="35" text-anchor="middle" fill="#a5b4c6" font-size="14">ZONE 02 · VARIED BRANCH LENGTHS</text>${lines}<text x="55" y="250" text-anchor="middle" fill="#a5b4c6" font-size="13">Supply</text><text x="730" y="250" text-anchor="middle" fill="#a5b4c6" font-size="13">Tank</text>${Object.entries(positions).map(([n,[x,y]])=>sensors.includes(n)?`<g class="sensor" role="button" tabindex="0" aria-label="Select ${n} as leak location" data-node="${n}" transform="translate(${x},${y})"><circle r="18" fill="#102c30" stroke="#65e2ce" stroke-width="2"/><circle r="5" fill="#65e2ce"/><text y="-29" text-anchor="middle" fill="#eef6fa" font-size="14">${n.replace('_',' · ')}</text><text class="node-reading" y="40" text-anchor="middle" fill="#a5b4c6" font-size="14">— m</text></g>`:`<circle cx="${x}" cy="${y}" r="${n==='R_SUP'||n==='T_OUT'?12:5}" fill="#183446" stroke="#658298" stroke-width="2"/>`).join('')}<text x="400" y="388" text-anchor="middle" fill="#8597aa" font-size="12">Schematic layout · branch lengths and parallel pressure valves retained in EPANET</text></svg>`;document.querySelectorAll('.sensor').forEach(el=>{const choose=()=>{$('node').value=el.dataset.node; $('chart-sensor').value=el.dataset.node; $('notice').textContent='Leak location selected. Run experiment to apply.'};el.onclick=choose;el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();choose()}}});}
drawNetwork();
$('method-button').onclick=()=>$('method-dialog').showModal();$('close-method').onclick=()=>$('method-dialog').close();
$('size').oninput=()=>$('size-value').textContent=['Small','Medium','Large'][+$('size').value];$('noise').oninput=()=>$('noise-value').textContent=`${(+$('noise').value).toFixed(2)} m`;
let data,current=null,step=0,timer=null,saved=[];
try{const stored=JSON.parse(localStorage.getItem('aquatrace-runs-v1')||'[]');if(Array.isArray(stored))saved=stored.slice(0,20).filter(x=>x&&typeof x==='object'&&Number.isInteger(x.seed));}catch{}
function stop(){clearInterval(timer);timer=null;$('play').textContent='Play';}
function configuration(){return {node:$('node').value,size:+$('size').value,demand:+$('demand').value,noise:+$('noise').value,seed:crypto.getRandomValues(new Uint32Array(1))[0]};}
function applyConfig(c){$('node').value=c.node;$('size').value=c.size;$('size').oninput();$('demand').value=c.demand;$('noise').value=c.noise;$('noise').oninput();if(c.node!=='none')$('chart-sensor').value=c.node;}
function start(c){const next=runExperiment(data,c);stop();current=next;step=29;applyConfig(c);$('timeline').disabled=false;$('play').disabled=false;$('save').disabled=false;render();$('notice').textContent='Experiment complete. Scrub the timeline or play the observations.';return summary();}
function summary(){return {node:current.config.node,noise:current.config.noise,demand:current.config.demand,delay:current.delay,falseAlarms:current.falseAlarms,finalScore:current.steps[29].score};}
function render(){const s=current.steps[step];$('timeline').value=step;$('time-label').textContent=`Step ${String(step).padStart(2,'0')} / 29`;$('reading-step').textContent=`Step ${String(step).padStart(2,'0')}`;
  $('network-state').textContent=s.leaking?'Leak active':'No leak active';$('network-state').classList.toggle('alert',s.leaking);
  document.querySelectorAll('.sensor').forEach(el=>{const k=sensors.indexOf(el.dataset.node),active=s.leaking&&el.dataset.node===current.config.node;el.querySelector('circle').setAttribute('stroke',active?'#ffad74':'#65e2ce');el.querySelector('circle').setAttribute('fill',active?'#51372c':'#102c30');el.querySelector('.node-reading').textContent=`${s.pressure[k].toFixed(2)} m`;});
  $('prediction').textContent=s.positive?'Leak signal':'No leak signal';$('prediction').style.color=s.positive?'var(--orange)':'var(--mint)';$('score').textContent=`${Math.round(s.score*100)}% model score · not calibrated confidence`;
  const drop=Math.max(...s.residual),index=s.residual.indexOf(drop);$('drop').innerHTML=`${drop.toFixed(2)} <small>m</small>`;$('drop-node').textContent=`${sensors[index]} · baseline minus observed`;
  $('delay').textContent=current.config.node==='none'?'Not applicable':current.delay===null?'Not detected':`${current.delay} steps`;$('false').textContent=`${current.falseAlarms} / ${current.config.node==='none'?30:10}`;
  $('readings').innerHTML=sensors.map((n,k)=>`<tr><td>${n}</td><td>${s.pressure[k].toFixed(2)} m</td><td style="color:${s.residual[k]>.5?'var(--orange)':'var(--muted)'}">${s.residual[k].toFixed(2)} m</td></tr>`).join('');drawChart();
}
function drawChart(){if(!current)return;const k=sensors.indexOf($('chart-sensor').value),values=current.steps.map(s=>s.pressure[k]),base=current.scenario.baseline[k],lo=Math.min(...values,base)-.4,hi=Math.max(...values,base)+.4;const x=i=>50+i*640/29,y=v=>190-(v-lo)/(hi-lo)*155;
  $('chart').innerHTML=`<svg viewBox="0 0 730 230" role="img" aria-label="Pressure at ${sensors[k]} across 30 observations, ranging from ${lo.toFixed(1)} to ${hi.toFixed(1)} metres of head"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#65e2ce" stop-opacity=".19"/><stop offset="1" stop-color="#65e2ce" stop-opacity="0"/></linearGradient></defs>${[0,.5,1].map(f=>{const v=lo+(hi-lo)*f;return `<path d="M50 ${y(v)}H690" stroke="#2a3a4b"/><text x="42" y="${y(v)+4}" text-anchor="end" fill="#a5b4c6" font-size="12">${v.toFixed(1)}</text>`}).join('')}<path d="M50 ${y(base)}H690" stroke="#a5b4c6" stroke-dasharray="6 5"/><path d="M50 190 L${values.map((v,i)=>`${x(i)},${y(v)}`).join(' L')} L690 190Z" fill="url(#area)"/><polyline points="${values.map((v,i)=>`${x(i)},${y(v)}`).join(' ')}" fill="none" stroke="#65e2ce" stroke-width="2.5"/>${current.config.node!=='none'?`<path d="M${x(10)} 25V190" stroke="#ffad74" stroke-dasharray="4 4"/><text x="${x(10)+7}" y="19" fill="#ffad74" font-size="12">Leak onset</text>`:''}<path d="M${x(step)} 30V190" stroke="#d8e6ef" opacity=".5"/><circle cx="${x(step)}" cy="${y(values[step])}" r="4" fill="#fff"/>${[0,10,20,29].map(i=>`<text x="${x(i)}" y="216" text-anchor="middle" fill="#a5b4c6" font-size="12">${i}</text>`).join('')}<text x="690" y="19" text-anchor="end" fill="#a5b4c6" font-size="12">Pressure (m)</text></svg>`;
}
function history(){const host=$('history');host.replaceChildren();if(!saved.length){host.innerHTML='<p class="empty">Your saved experiments will appear here.</p>';return;}saved.forEach((c,i)=>{let r;try{r=runExperiment(data,c)}catch{return;}const row=document.createElement('div');row.className='history-row';const description=document.createElement('div');description.className='summary';const title=document.createElement('strong');title.textContent=`${c.node==='none'?'No-leak control':c.node+' · '+['Small','Medium','Large'][c.size]}`;const sub=document.createElement('small');sub.textContent=`Demand ${c.demand*100}% · noise ${c.noise.toFixed(2)} m · seed ${c.seed}`;description.append(title,sub);const result=document.createElement('span');result.textContent=`${c.node==='none'?'Control':r.delay===null?'Not detected':r.delay+' steps to detection'} · ${r.falseAlarms} false positives`;const replay=document.createElement('button');replay.className='secondary';replay.textContent='Replay';replay.onclick=()=>{start(c);$('network').scrollIntoView({block:'center',behavior:'smooth'})};const remove=document.createElement('button');remove.className='secondary';remove.textContent='Remove';remove.setAttribute('aria-label',`Remove saved experiment ${i+1}`);remove.onclick=()=>{saved.splice(i,1);persist();history()};row.append(description,result,replay,remove);host.append(row);});}
function persist(){try{localStorage.setItem('aquatrace-runs-v1',JSON.stringify(saved));return true;}catch{$('notice').textContent='Browser storage unavailable. Runs remain available for this visit only.';return false;}}
$('run').onclick=()=>{try{start(configuration());}catch(e){$('notice').textContent=e.message;}};
$('timeline').oninput=()=>{stop();step=+$('timeline').value;render()};$('chart-sensor').onchange=drawChart;
$('play').onclick=()=>{if(timer){stop();return;}if(step===29)step=0;render();$('play').textContent='Pause';timer=setInterval(()=>{step++;render();if(step===29)stop()},450)};
$('save').onclick=()=>{if(saved.length>=20){$('notice').textContent='Notebook is full (20 experiments). Remove a run before saving another.';return;}saved.unshift({...current.config});const ok=persist();history();if(ok)$('notice').textContent='Experiment saved on this device.';};
function registerTools(){const context=document.modelContext;if(!context?.registerTool)return;const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});try{Promise.resolve(context.registerTool({name:'run_water_leak_experiment',title:'Run a water-leak experiment',description:'Run a simulated leak experiment and update the network, charts and detector results.',inputSchema:{type:'object',properties:{node:{type:'string',enum:['none',...sensors]},size:{type:'integer',enum:[0,1,2]},demand:{type:'number',enum:[.7,1,1.3]},noise:{type:'number',minimum:0,maximum:.5},seed:{type:'integer'}},required:['node','size','demand','noise','seed'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input!=='object')throw Error('Expected experiment parameters.');return start(input);}},{signal:lifecycle.signal})).catch(()=>{});}catch{}}
fetch('data.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(result=>{data=result;$('run').disabled=false;$('run').textContent='Run experiment →';history();registerTools();start({...configuration(),seed:42});$('notice').textContent='Example experiment loaded. Change the controls to test a different scenario.';}).catch(()=>{$('notice').textContent='Could not load simulation data. Please reload to retry.'});
